[DataContractAttribute]
class HSMobileOpsLocationRequest
{
    DataAreaId       dataAreaId;
    InventLocationId warehouseId;
    WMSLocationId    locationId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public InventLocationId parmWarehouseId(InventLocationId _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LocationId')]
public WMSLocationId parmLocationId(WMSLocationId _value = locationId)
{
    locationId = _value;
    return locationId;
}
